\begin{proposition}[Scalar Minty representation]\label{prop:minty}
For a monotone operator $f$, let $J_f$ denote its \emph{resolvent}, defined according to its orientation in the table below. The operator is maximal if and only if $J_f$ is an everywhere defined nondecreasing $1$-Lipschitz function. In that case, its graph is the following set, and the displayed map from $s\in\R$ onto $\gra(f)$ is a homeomorphism:
\begin{equation}\label{eq:minty}
 \begin{array}{c|cc}
  &J_f&\gra(f)\\ \hline
  f\text{ nondecreasing}&(\id+f)^{-1}
   &\{(J_f(s),s-J_f(s)):s\in\R\}\\[4pt]
  f\text{ nonincreasing}&(\id-f)^{-1}
   &\{(J_f(s),J_f(s)-s):s\in\R\}
 \end{array}
\end{equation}
Conversely, every everywhere defined nondecreasing $1$-Lipschitz function is a resolvent, in either orientation.
\end{proposition}

\begin{proposition}[Pointwise characterization of maximality]\label{prop:pointwisemaximality}
Let $f:\R\rightrightarrows\R$ be a nondecreasing monotone operator,
possibly with empty values. Then $f$ is maximally monotone if and only if,
\begin{equation}\label{eq:maximalvalues}
\forall x\in\R:\qquad  f(x)=\left[\sup\bigcup_{y<x}f(y),\ \inf\bigcup_{y>x}f(y)\right]\cap\R,
\end{equation}
where the supremum and infimum are taken in the extended real line,
$\sup\varnothing=-\infty$, $\inf\varnothing=+\infty$.



\end{proposition}

\begin{proposition}[Sums and domain--range characterization]\label{prop:sums}\label{prop:domainrange}
Let $f,g$ be maximal with the same orientation. If $\dom f\cap\dom g\ne\varnothing$, then $f+g$ is maximal with that orientation and
\[
 \ran(f+g)=\ran f+\ran g.
\]
Moreover, a nondecreasing monotone operator $h$ is maximal if and only if
\begin{equation}\label{eq:domainrange}
 \ran(h+\id)\text{ is an interval},\qquad \ran h+\dom h=\R.
\end{equation}
For a nonincreasing operator, replace these conditions by
$\ran(h-\id)$ being an interval and $\ran h-\dom h=\R$.
\end{proposition}

\begin{proposition}[Composition]\label{prop:composition}
Let $f,g$ be maximal with orientations $\sigma,\tau\in\{1,-1\}$, where $1$ denotes nondecreasing, and suppose $g\circ f\ne\varnothing$. The composite is monotone with the expected orientation $\varepsilon=\sigma\tau$ if and only if
\begin{equation}\label{eq:rectangle}
 \forall z\in\R:\qquad
 f^{-1}(z)\text{ or }g(z)\text{ has at most one element}.
\end{equation}
Under this condition,
\begin{equation}\label{eq:compositionmax}
 g\circ f\text{ is maximal in orientation }\varepsilon
 \quad\Longleftrightarrow\quad \dom f+\varepsilon\ran g=\R.
\end{equation}
\end{proposition}

\begin{lemma}[Maximality under logarithms]\label{lem:logmaximal}
Let $f:\R\rightrightarrows\R$ be maximally monotone in either orientation.
If $\ran f\subset[0,\infty)$ and there exists $c>0$ with $c\in\ran f$,
then $\log f$ is maximally monotone with the same orientation.
\end{lemma}

\begin{example}[A zero-degeneracy obstruction]\label{ex:zero}
The increasing maximal operators
\[
 \begin{aligned}
  \forall x\in\R:&\qquad f(x)=\max\{x,0\},\\
  \forall x<0:&\qquad g(x)=-1/x
 \end{aligned}
\]
have nonnegative ranges. Nevertheless, $fg$ is zero on $(-\infty,0)$ and empty elsewhere, so it is not maximal and its range is not $\ran f\,\ran g$. Thus nonnegativity alone does not suffice for product closure.
\end{example}

\begin{definition}[Pointwise resolvent order]\label{def:order}
For maximal operators of a fixed orientation, define the \emph{pointwise resolvent order} by
\begin{equation}\label{eq:order}
 f\leq g\quad\Longleftrightarrow\quad
 \begin{cases}
 J_f\geq J_g&\text{on }\Mu,\\
 J_f\leq J_g&\text{on }\Md.
 \end{cases}
\end{equation}
All comparisons of functions in this definition are pointwise on $\R$.
\end{definition}

\begin{proposition}[Separated-graph characterization]\label{prop:comparison}
For $f,g\in\Mu$,
\begin{equation}\label{eq:separated}
 \begin{aligned}
 f\leq g\quad\Longleftrightarrow\quad&
 \forall(x,u)\in\gra f,\ \forall(y,v)\in\gra g:\ \ x<y\ \Longrightarrow\ u\leq v.
 \end{aligned}
\end{equation}
For $f,g\in\Md$, replace $x<y$ by $x>y$. Consequently, for any $\lambda>0$, \eqref{eq:order} is unchanged when $J_f,J_g$ are replaced by $J_{\lambda f},J_{\lambda g}$.
At every common domain point,
\begin{equation}\label{eq:height}
 f\leq g\quad\Longrightarrow\quad
 \inf f(x)\leq\inf g(x),\qquad \sup f(x)\leq\sup g(x).
\end{equation}
If $f,g$ have the same domain, the endpoint inequalities in \eqref{eq:height} also imply $f\leq g$.
\end{proposition}

\begin{lemma}[Resolvent comparison with an operator value]\label{lem:resolventvalue}
Let $f\in\Mu\cup\Md$, $x\in\dom f$, and $u\in\R$.
If $f$ is nondecreasing ($f\in\Mu$), then
\begin{equation}\label{eq:resolventvalue}
 J_f(x+u)\leq x\Longleftrightarrow u\in f(x)_-,\qquad
 J_f(x+u)\geq x\Longleftrightarrow u\in f(x)_+.
\end{equation}
If $f$ is nonincreasing ($f\in\Md$), then
\begin{equation}\label{eq:resolventvaluedecreasing}
 J_f(x-u)\geq x\Longleftrightarrow u\in f(x)_-,\qquad
 J_f(x-u)\leq x\Longleftrightarrow u\in f(x)_+.
\end{equation}
\end{lemma}

\begin{definition}[Order on intervals]\label{def:intervalorder}
Using the upward and downward hulls defined in~\eqref{eq:hull_p_m}, for nonempty intervals $I,J\subset\R$, define
\begin{equation}\label{eq:intervalorder}
 I\leq J\quad\Longleftrightarrow\quad
 I_+\supseteq J_+\ \text{and}\ I_-\subseteq J_-.
\end{equation}
\end{definition}

\begin{proposition}[Domains and ranges under comparison]\label{prop:orderdomains}
Let $f,g$ be maximal operators of the same orientation. If $f\leq g$, then, in the interval order of Definition~\ref{def:intervalorder},
\begin{equation}\label{eq:domainrangeorder}
 \ran f\leq\ran g,\qquad
 \begin{cases}
  \dom g\leq\dom f,&f,g\in\Mu,\\
  \dom f\leq\dom g,&f,g\in\Md.
 \end{cases}
\end{equation}
At each $x\in\dom f\cap\dom g$, one also has $f(x)\leq g(x)$ in this interval order.
\end{proposition}

\begin{proposition}[Inversion and elementary compatibility]\label{prop:inversion}
For maximal operators,
\begin{equation}\label{eq:inverseorder}
 \begin{array}{ll}
 f,g\in\Mu:&f\leq g\ \Longleftrightarrow\ f^{-1}\geq g^{-1},\\
 f,g\in\Md:&f\leq g\ \Longleftrightarrow\ f^{-1}\leq g^{-1}.
 \end{array}
\end{equation}
If $f\leq g$ and $h$ has their orientation, then, whenever the displayed operations are maximal in that orientation,
\begin{equation}\label{eq:sumorder}
 f+h\leq g+h.
\end{equation}
The analogous inequality holds for products when all ranges are nonnegative.
For $h$ of either orientation, if both composites being compared are maximal in the expected orientation, then
\begin{equation}\label{eq:compositionorder}
 f\circ h\leq g\circ h,\qquad
 \begin{cases}
 h\circ f\leq h\circ g&h\in\Mu,\\
 h\circ f\geq h\circ g&h\in\Md.
 \end{cases}
\end{equation}

\end{proposition}

\begin{lemma}[Survival comparison]\label{lem:survivalcomparison}
For a real random variable $X$ and $\alpha\in\Md$,
\begin{equation}\label{eq:survivaltest}
 \SSS[X]\leq\alpha
 \quad\Longleftrightarrow\quad
 \bigl[\forall(t,u)\in\gra\alpha:\quad \PP(X>t)\leq u\bigr].
\end{equation}
Equivalently, $\TT[X]\leq\alpha^{-1}$.
\end{lemma}

\begin{theorem}[Conditional completeness]\label{thm:lattice}
Let $(f_a)_{a\in A}$ be a nonempty family of maximally monotone operators of a fixed orientation. 
Its infimum exists if and only if the family has a lower bound; its supremum exists if and only if it has an upper bound. 
They are characterized by
\begin{equation}\label{eq:lattice}
\begin{array}{c|cc}
 &J_{\inf_a f_a}&J_{\sup_a f_a}\\ \hline
 \Mu&\sup_aJ_{f_a}&\inf_aJ_{f_a}\\
 \Md&\inf_aJ_{f_a}&\sup_aJ_{f_a}.
\end{array}
\end{equation}
\end{theorem}

\begin{lemma}[Inversion and extrema]\label{lem:inverseextrema}
Let $(f_a)_{a\in A}$ be a nonempty family in $\Mu$ or in $\Md$.
If either side of an identity in the table exists, then so does the other, and they are equal.
\[
 \begin{array}{c|cc}
  &(\inf_a f_a)^{-1}&(\sup_a f_a)^{-1}\\ \hline
  \Mu&\sup_a(f_a^{-1})&\inf_a(f_a^{-1})\\
  \Md&\inf_a(f_a^{-1})&\sup_a(f_a^{-1}).
 \end{array}
\]
\end{lemma}

\begin{definition}[Infimum and supremum of intervals]\label{def:intervalextrema}
Using the notation of Definition~\ref{def:intervalorder}, for a finite nonempty family $(I_a)_{a\in A}$ of nonempty intervals define
\begin{align*}
 \inf_{a\in A}\{I_a\}
   &=\left(\bigcup_{a\in A}(I_a)_+\right)
     \cap\left(\bigcap_{a\in A}(I_a)_-\right),
     \\
 \sup_{a\in A}\{I_a\}&=\left(\bigcup_{a\in A}(I_a)_-\right)
     \cap\left(\bigcap_{a\in A}(I_a)_+\right).
\end{align*}
These intervals are the greatest lower bound and least upper bound, respectively, in the interval order; they need not be members of the original family. Consequently, for nonempty intervals $I,J$,
\begin{equation}\label{eq:intervalorderextrema}
 I\leq J\quad\Longleftrightarrow\quad
 \inf\{I,J\}=I\quad\Longleftrightarrow\quad\sup\{I,J\}=J.
\end{equation}
\end{definition}

\begin{proposition}[Domains, ranges, and values of finite extrema]\label{prop:finitevalues}\label{prop:extremadomains}
Let $(f_a)_{a\in A}$ be a finite nonempty family in $\Mu$ or in $\Md$. Then
\begin{equation}\label{eq:extremadomains}
\begin{array}{c|cc}
 &\dom(\inf_a f_a)&\dom(\sup_a f_a)\\ \hline
 \Mu&\sup_a\{\dom f_a\}&\inf_a\{\dom f_a\}\\
 \Md&\inf_a\{\dom f_a\}&\sup_a\{\dom f_a\},
\end{array}
\end{equation}
and, in both orientations,
\begin{equation}\label{eq:extremaranges}
 \ran(\inf_a f_a)=\inf_a\{\ran f_a\},\qquad
 \ran(\sup_a f_a)=\sup_a\{\ran f_a\}.
\end{equation}
At every $x\in D:=\bigcap_a\dom f_a$,
\begin{align}\label{eq:finitevalues}
 (\inf_a f_a)(x)&=\inf_a\{f_a(x)\}
   =[\inf_a\inf f_a(x),\ \inf_a\sup f_a(x)]\cap\R,\\
 (\sup_a f_a)(x)&=\sup_a\{f_a(x)\}
   =[\sup_a\inf f_a(x),\ \sup_a\sup f_a(x)]\cap\R.\notag
\end{align}
\end{proposition}

\begin{proposition}[Finite algebraic identities]\label{prop:finiteextremaoperations}
Let $A$ be finite and nonempty, $(f_a)_{a\in A}\in\Mu^A$, and $h\in\Mu$.
If, for every $a\in A$, $h+f_a\in\Mu$, then
\begin{equation}\label{eq:finitealgebraic}
 h+(\inf_a f_a)=\inf_a(h+f_a),\qquad
 h+(\sup_a f_a)=\sup_a(h+f_a).
\end{equation}
For products, they hold if $\ran h\subset[0,\infty)$ and, for every $a\in A$, $hf_a\in\Mu$.
All these statements also hold with $\Mu$ replaced by $\Md$.
\end{proposition}

\begin{proposition}[Composition and extrema]\label{prop:extremacomposition}
Let $A$ be finite and nonempty, let $(f_a)_{a\in A}$ belong to one
maximal orientation class, and let $h$ be maximal with specified
orientation.
If every $f_a\circ h$ is maximal in the expected orientation, then
\begin{equation}\label{eq:finitecomposition}
 (\inf_a f_a)\circ h=\inf_a(f_a\circ h),\qquad
 (\sup_a f_a)\circ h=\sup_a(f_a\circ h).
\end{equation}
If instead every $h\circ f_a$ is maximal in the expected orientation,
then
\[
 \begin{array}{c|cc}
  &h\circ(\inf_a f_a)&h\circ(\sup_a f_a)\\ \hline
  h\in\Mu&\inf_a(h\circ f_a)&\sup_a(h\circ f_a)\\
  h\in\Md&\sup_a(h\circ f_a)&\inf_a(h\circ f_a).
 \end{array}
\]
\end{proposition}

\begin{proposition}[Sums and nonnegative products]\label{prop:probability}
Let $X_1,\ldots,X_n$ be real random variables on one probability space,
with $\SSS[X_i]\leq\alpha_i\in\Md$ and
$\bigcap_i\ran\alpha_i\ne\varnothing$. Then
\begin{equation}\label{eq:probsum}
 \SSS\!\left[\sum_{i=1}^nX_i\right]
 \leq n(\alpha_1\boxplus\cdots\boxplus\alpha_n).
\end{equation}
If additionally $X_i\geq0$ almost surely,
$\dom\alpha_i\subset[0,\infty)$, and
$\alpha_1^{-1}\cdots\alpha_n^{-1}$ is maximal, then
\begin{equation}\label{eq:probproduct}
 \SSS\!\left[\prod_{i=1}^nX_i\right]
 \leq n(\alpha_1\boxtimes\cdots\boxtimes\alpha_n).
\end{equation}
\end{proposition}

\begin{corollary}[Centered sums and products]\label{cor:centered}
Suppose $\SSS[|X-c|]\leq\alpha$ and $\SSS[|Y-d|]\leq\beta$, where
$\alpha,\beta\in\Md$ have nonnegative domains and
$\ran\alpha\cap\ran\beta\ne\varnothing$.
Whenever all the displayed parallel expressions are maximal,
\[
 \SSS[|X+Y-c-d|]\leq2(\alpha\boxplus\beta).
\]
For $c,d\ne0$, one also has
\begin{equation}\label{eq:centeredproduct}
 \SSS[|XY-cd|]\leq
 2\left((\alpha\boxtimes\beta)
 \boxplus\alpha\circ\frac{\id}{|d|}
 \boxplus\beta\circ\frac{\id}{|c|}\right).
\end{equation}
If $d=0$, omit the term containing $\alpha\circ(\id/|d|)$;
if $c=0$, omit the term containing $\beta\circ(\id/|c|)$.
\end{corollary}

\begin{proposition}[Weighted parallel-sum envelopes]\label{prop:envelopes}
Let $\alpha_1,\ldots,\alpha_n\in\Md$ have common range $D$.
For $\theta_i>0$ with $\sum_i\theta_i=1$,
\begin{equation}\label{eq:envelopes}
 \inf_i\bigl(\alpha_i\circ(\theta_i\id)\bigr)
 \leq\alpha_1\boxplus\cdots\boxplus\alpha_n
 \leq\sup_i\bigl(\alpha_i\circ(\theta_i\id)\bigr).
\end{equation}
\end{proposition}

\begin{definition}[Aumann integral]\label{def:aumannintegral}
Let $(\Theta,\mathcal A,\mu)$ be a measure space and let
$h:\Theta\rightrightarrows\R$ be measurable with nonempty closed
values. Its \emph{Aumann integral} \cite{Aumann1965} is
\begin{equation}\label{eq:aumann}
 \int_\Theta^{\mathrm A}h\,d\mu
 :=\left\{\int_\Theta s\,d\mu:
       s\in L^1(\mu),\quad \text{for almost every }\theta:
       \ s(\theta)\in h(\theta)\right\}.
\end{equation}
Here measurability means that, for every open set $O\subseteq\R$,
$\{\theta:h(\theta)\cap O\ne\varnothing\}\in\mathcal A$.
For interval-valued maps, this is equivalent to measurability of the
two extended-real endpoints. If $h=[\ell,u]$ with
$\ell,u\in L^1(\mu)$, then
\begin{equation}\label{eq:aumanninterval}
 \int_\Theta^{\mathrm A}h\,d\mu
 =\left[\int_\Theta\ell\,d\mu,\int_\Theta u\,d\mu\right].
\end{equation}
\end{definition}

\begin{proposition}[Inverse-area identity]\label{prop:area}
Let $\alpha\in\Md$ have graph contained in $[0,\infty)^2$, with
$(0,\infty)\subseteq\dom\alpha$ and
$\lim_{t\to\infty}\sup\alpha(t)=0$.
Then $\alpha^{-1}$ is defined on $(0,\infty)$ and
\begin{equation}\label{eq:inversearea}
 \int_0^\infty\alpha(t)\,dt
 =\int_0^\infty\alpha^{-1}(p)\,dp\in[0,\infty].
\end{equation}
\end{proposition}

\begin{corollary}[Moments]\label{cor:moments}
For $Y\geq0$ and $r>0$,
\begin{equation}\label{eq:momentidentities}
 \E [Y^r]
 =r\int_0^\infty t^{r-1}\SSS[Y](t)\,dt
 =\int_0^1\bigl(\TT[Y](p)\bigr)^r\,dp.
\end{equation}
\end{corollary}

\begin{corollary}[Change of pivot to the mean]\label{prop:pivots}
Let $X$ be real-valued and $c\in\R$.
If $\SSS[|X-c|]\leq\beta\in\Md$, with nonnegative values on
$(0,\infty)\subseteq\dom\beta$, and
$M:=\int_0^\infty\beta(t)\,dt<\infty$, then $X\in L^1$ and
\begin{equation}\label{eq:meanpivot}
 |\E X-c|\leq M,\qquad
 \SSS[|X-\E X|]\leq\beta\circ(\id-M).
\end{equation}
\end{corollary}

\begin{definition}[Hardy transform]\label{def:hardytransform}
Let $f\in\Md$ be integrable and satisfy
$0=\inf\dom f<\sup\dom f$.
Its \emph{Hardy transform} is\footnote{Using Definitions~\ref{def:area}
and~\ref{def:familyintegral}, with Lebesgue measure on $(0,1)$ for the operator integral.}
\begin{equation}\label{eq:hardyfamily}
 \mathcal H(f)=\int_{(0,1)}
 \left.(f\circ(r\id))\right|_{\operatorname{int}\dom f}\,dr.
\end{equation}
\end{definition}

\begin{lemma}[Convexity and concavity of the Hardy transform]\label{lem:hardyconvexity}
Let $f\in\Md$ be integrable and satisfy
$0=\inf\dom f<\sup\dom f$.
If $f$ is convex (respectively, concave), then $\mathcal H(f)$ is convex
(respectively, concave).
\end{lemma}

\begin{lemma}[Variational formulas for the Hardy transform]\label{lem:hardyvariational}
For $X\in L^1$ and $0<p<1$,
\begin{align}\label{eq:hardyvariational}
 \mathcal H(\TT[X])(p)
 &=\min_{a\in\R}\left\{a+\frac1p\E\left[(X-a)_+\right]\right\}
 =\frac1p\sup_{\substack{0\leq Z\leq1\\\E Z=p}}\E[XZ],
\end{align}
where $Z$ ranges over random variables on the original probability space. The value of the completed quantile operator at $p$ is the minimizer set:
\[
 \TT[X](p)=\operatorname*{argmin}_{a\in\R}
 \left\{a+\frac1p\E\left[(X-a)_+\right]\right\}.
\]
\end{lemma}

\begin{proposition}[Superadditive transformation of an odd median \cite{Ruger1978,Morgenstern1980}]
\label{prop:mediantransform}
Let $r\ge0$ be an integer and set
\[
 n=2r+1,
 \qquad
 M(x):=\operatorname{med}(x_1,\ldots,x_n).
\]
For $a\in[0,\infty)^n$, write
\[
 a_{(1)}\le\cdots\le a_{(n)}
\]
for its ordered coordinates. Then
\begin{equation}\label{eq:mediantransform}
 M^\sharp(a)
 =
 \min_{1\le\ell\le r+1}
 \frac{a_{(1)}+\cdots+a_{(r+\ell)}}{\ell}.
\end{equation}
\end{proposition}

\begin{lemma}[Area inequality for monotone aggregation]
\label{lem:aggregationarea}
Let $f_1,\ldots,f_n\in\Md$ have nonnegative values on their common
domain interior $(0,L)$. If $0<b\le L$ is finite and, for every
$i\in[n]$, $\int_0^b f_i<\infty$, then
\begin{equation}\label{eq:aggregationarea}
 \int_0^b F(f_1,\ldots,f_n)
 \le
 F^\sharp\left(\int_0^b f_1,\ldots,\int_0^b f_n\right).
\end{equation}
\end{lemma}

\begin{proposition}[Aggregation of Hardy tail profiles]
\label{prop:hardytailaggregation}
Let $X_1,\ldots,X_n$ be nonnegative integrable random variables on
one probability space. For every $p\in(0,1)$,
\begin{equation}\label{eq:hardytailaggregation}
 \mathcal H\left(\TT[F(X_1,\ldots,X_n)]\right)(p)
 \le
 F^\sharp\left(
 \mathcal H(\TT[X_1])(p),\ldots,
 \mathcal H(\TT[X_n])(p)
 \right).
\end{equation}
\end{proposition}

\begin{proposition}[Hardy bounds from convex transformations]\label{prop:hardyprofiles}
Let $\alpha\in\Md$ be single-valued, continuous and strictly decreasing
on its open interval domain $D$, mapping $D$ onto $(0,L)$ with
$0<L\leq\infty$.
If, for some $\kappa>1$, $t\mapsto\alpha(t)^{-1/\kappa}$ is convex on $D$, then $\mathfrak H(\alpha)$ is defined and
\begin{equation}\label{eq:hardypowerbound}
 \mathfrak H(\alpha)
 \leq\left(\frac\kappa{\kappa-1}\right)^\kappa\alpha.
\end{equation}
If instead $t\mapsto-\log\alpha(t)$ is convex on $D$, then $\mathfrak H(\alpha)$ is defined and
\begin{equation}\label{eq:hardyexponentialbound}
 \mathfrak H(\alpha)\leq e\alpha.
\end{equation}
The constants are attained for $\alpha=CP_\kappa$ and
$\alpha=C\mathcal E$, respectively, with $C>0$.
\end{proposition}

\begin{proposition}[Power and exponential convex transformations]\label{prop:convextransforms}
Let $\varphi:(0,\infty)\to\R$ be continuous. If, for every $\kappa>0$, $x\mapsto\varphi(x^{-\kappa})$ is convex on $(0,\infty)$, then $x\mapsto\varphi(e^{-x})$ is convex on $\R$. The converse holds when $\varphi$ is nondecreasing. The corresponding concave statements hold, with $\varphi$ nonincreasing for the converse.
\end{proposition}

\begin{theorem}[Sharpness of Hardy tail aggregation]
\label{thm:hardytailaggregationsharp}
Let $F:[0,\infty)^n\to[0,\infty)$ be continuous, coordinatewise
nondecreasing, and positively homogeneous.
For every $p\in(0,1)$ and $a\in[0,\infty)^n$,
\begin{equation}\label{eq:hardytailaggregationsharp}
 \begin{aligned}
 F^\sharp(a)=\sup\Bigl\{&
 \mathcal H\left(\TT[F(X_1,\ldots,X_n)]\right)(p):\quad
 \forall i\in[n]:\ \mathcal H(\TT[X_i])(p)=a_i,\\
 &X_1,\ldots,X_n\text{ nonnegative and finite-valued}
 \Bigr\}.
 \end{aligned}
\end{equation}
The same supremum is obtained by restricting to comonotone variables.
\end{theorem}

\begin{corollary}[Sharp Hardy bound for an odd median]
\label{cor:hardymedian}
Let $r\ge0$ be an integer, $n=2r+1$, and
$X_1,\ldots,X_n$ be nonnegative integrable random variables on
one probability space. Then
\begin{equation}\label{eq:hardytailmedian}
 \mathcal H\left(\TT[\operatorname{med}(X_1,\ldots,X_n)]\right)
 \le
 \inf_{1\le\ell\le r+1}
 \inf_{\substack{J\subseteq[n]\\|J|=r+\ell}}
 \frac1\ell\sum_{i\in J}\mathcal H(\TT[X_i]).
\end{equation}
This bound is sharp at every fixed $p\in(0,1)$, already for
nonnegative finite-valued comonotone variables.
\end{corollary}

\begin{proposition}[Universal quantile envelope as a lattice supremum]\label{prop:hardyoptimality}
Let $\mu_1,\ldots,\mu_n$ be integrable probability laws.
\begin{equation}\label{eq:hardylatticesup}
\frac1n\sum_{i=1}^n\mathcal H(\TT[\mu_i])
 =\sup_{\substack{m\geq1\\X_{i,j}\sim\mu_i\\1\leq i\leq n,\ 1\leq j\leq m}}
   \TT\!\left[\frac1{nm}\sum_{i=1}^n\sum_{j=1}^mX_{i,j}\right],
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:hardy-geometric-comparison}
Let $q$ satisfy Definition~\ref{def:geometrichardytransform}.
The transform $\mathcal G$ preserves order on this class, and
$q\leq\mathcal G(q)$. If, moreover, $q\in L^1(I)$, then
\begin{equation}\label{eq:hardy-geometric-comparison}
 q\leq \mathcal G(q)\leq\mathcal H(q).
\end{equation}
\end{lemma}

\begin{lemma}[P\'olya--Knopp inequality \cite{HardyLittlewoodPolya1952}]
\label{lem:local-polya-knopp}
Let $q$ be as in Definition~\ref{def:geometrichardytransform}.
For every $r>0$ and $0<a\leq1$,
\begin{equation}\label{eq:local-polya-knopp}
 \int_0^a\mathcal G(q)^r
 \leq\mathrm e\int_0^a q^r.
\end{equation}
\end{lemma}

\begin{lemma}[Logarithmic endpoint control]\label{lem:local-endpoint}
Let $q_\Delta\in\Md$ satisfy
$(0,1)\subseteq\operatorname{int}\dom q_\Delta$ and have
nonnegative values on $(0,1)$.
Let $Z$ take values in a metric space $(E,d_E)$, let $Z'$ be an
independent copy, and suppose that, for every real $1$-Lipschitz
function $f$ on $E$, $\TT[|f(Z)-f(Z')|]\leq q_\Delta$.
Let $h:E\to\R$ and $U:E\to[0,\infty)$ be measurable, with
$m:=\E\left[U(Z)\right]<\infty$. If, for some $C>0$,
\begin{equation}\label{eq:local-endpoint-modulus}
 \forall x,y\in E:\qquad
 |h(x)-h(y)|\leq C e^{U(x)+U(y)}d_E(x,y),
\end{equation}
then, for $0<a<1$, $s>0$ and $t\in q_\Delta(a)$,
\begin{equation}\label{eq:local-endpoint-tail}
 \PP\bigl(|h(Z)-h(Z')|>Ce^s t\bigr)
 \leq a+\frac{2m}{s}.
\end{equation}
\end{lemma}

\begin{theorem}[Randomized Lipschitz control]
\label{the:concentration_bounded_variations}
Let $(E,d_E)$ and $(E',d_{E'})$ be metric spaces, let $Z$ be an
$E$-valued random variable, and let $Z'$ be an independent copy.
Let $n\geq1$, and let $\Phi:E\to E'$ and, for $i\in[n]$,
$\Lambda_i:E\to[0,\infty)$ be measurable. Suppose that
\begin{equation}\label{eq:local-modulus}
 \forall z,z'\in E:\qquad
 d_{E'}(\Phi(z),\Phi(z'))
 \leq d_E(z,z')\prod_{i=1}^n
             \max\{\Lambda_i(z),\Lambda_i(z')\}.
\end{equation}
Let $q_\Delta,q_1,\ldots,q_n\in\Md$ have domain interior $I$ and
nonnegative values there, with
\begin{equation}\label{eq:local-input}
 \begin{aligned}
 &\forall f:E\to\R\text{ $1$-Lipschitz}:\qquad
   \TT[|f(Z)-f(Z')|]\leq q_\Delta,\\
 &\forall i\in[n]:\qquad \TT[\Lambda_i(Z)]\leq q_i.
 \end{aligned}
\end{equation}
Assume
\[
 \int_0^1\log_+\left(q_\Delta(s)\prod_iq_i(s)\right)\,ds<\infty.
\]
For every $1$-Lipschitz $g:E'\to\R$, if no input profile vanishes
identically on $I$, then
\begin{equation}\label{eq:local-geometric}
 \TT[|g(\Phi(Z))-g(\Phi(Z'))|]
 \leq\left.
 \left[\mathcal G\left(q_\Delta\prod_iq_i\right)
       \circ(\id/3)\right]\right|_I.
\end{equation}
If an input profile vanishes identically on $I$, then
$|g(\Phi(Z))-g(\Phi(Z'))|=0$ almost surely.
In all cases, for every $r>0$ such that
$q_\Delta\prod_iq_i\in L^r(I)$,
\begin{equation}\label{eq:local-moment}
 \bigl\|g(\Phi(Z))-g(\Phi(Z'))\bigr\|_{L^r}
 \leq(3\mathrm e)^{1/r}
       \left\|q_\Delta\prod_iq_i\right\|_{L^r(I)}.
\end{equation}
\end{theorem}

\begin{proposition}[Lower bound for the moment scale]
\label{prop:local-moment-sharpness}
Let $q_\Delta,q_1,\ldots,q_n$ satisfy the hypotheses of
Theorem~\ref{the:concentration_bounded_variations}.
There exist a metric space $E$, an $E$-valued random vector $Z$,
measurable controls $\Lambda_i$, and a scalar map $\Phi:E\to\R$
satisfying \eqref{eq:local-modulus} and \eqref{eq:local-input}
with these profiles, such that for every $r>0$,
\begin{equation}\label{eq:local-moment-lower}
 \bigl\|\Phi(Z)-\Phi(Z')\bigr\|_{L^r}
 \geq2^{-1/r}
       \left\|q_\Delta\prod_iq_i\right\|_{L^r(I)}.
\end{equation}
\end{proposition}

\begin{remark}[Centering and unequal probability levels]
For $V=g(\Phi(Z))$ and any median $m_V$, the independent-copy
comparison \eqref{eq:independentcopy} gives, when no input profile
vanishes identically,
\begin{equation}\label{eq:local-median}
 \TT[|V-m_V|]\leq
 \left.
 \left[\left(q_\Delta\mathcal G\left(\prod_iq_i\right)\right)
       \circ(\id/6)\right]\right|_I.
\end{equation}
In all cases, for every $r>0$ such that
$q_\Delta\prod_iq_i\in L^r(I)$,
\[
 \|V-m_V\|_{L^r}\leq(6\mathrm e)^{1/r}
              \left\|q_\Delta\prod_iq_i\right\|_{L^r(I)}.
\]
The zero-profile cases are interpreted as above.
For $r\geq1$ and $q_\Delta\prod_iq_i\in L^r(I)$, integrability follows and
conditional Jensen gives
\begin{equation}\label{eq:local-mean}
 \|V-\E V\|_{L^r}\leq\|V-V'\|_{L^r}
 \leq(3\mathrm e)^{1/r}
       \left\|q_\Delta\prod_iq_i\right\|_{L^r(I)}.
\end{equation}
\end{remark}

\begin{proposition}[Network tail profiles]\label{prop:local-network}
Suppose that $Z$ satisfies the first inequality in
\eqref{eq:local-input} with a nonnegative profile $q_\Delta$ on
$I=(0,1)$ such that $\int_0^1\log_+q_\Delta<\infty$.
For every Hilbert--Schmidt $1$-Lipschitz observation $g$, put
$V=g(\Phi(Z))$ and let $m_V$ be a median. Then, for $0<u<1$,
\begin{equation}\label{eq:local-network-profile}
 \begin{aligned}
 \TT[|V-m_V|](u)
 &\leq Dq_\Delta(u/6)\\
 &\quad{}\times
 \prod_{\ell=1}^L
 \mathcal G\!\left(
 \max\{m_x,m_\ell\}
 +\frac{q_\Delta}{\sqrt{\min\{Np_0,p_\ell+p_{\ell-1}\}}}
 \right)(u/12).
 \end{aligned}
\end{equation}
Profiles use the completion convention on $I$.
\end{proposition}

\begin{example}[Power tails]
If, for some $A,\alpha>0$, $q_\Delta(u)\leq Au^{-\alpha}$, then
\begin{equation}\label{eq:local-network-power}
 \begin{aligned}
 \TT[|V-m_V|](u)
 &\leq DAe^{\alpha L}(6/u)^\alpha\\
 &\quad{}\times
 \prod_{\ell=1}^L\left(
 \max\{m_x,m_\ell\}
 +\frac{A(12/u)^\alpha}
        {\sqrt{\min\{Np_0,p_\ell+p_{\ell-1}\}}}
 \right).
 \end{aligned}
\end{equation}
This follows by using, for $m,c\geq0$,
$\mathcal G(m+c\,\id^{-\alpha})(v)
 \leq e^\alpha(m+cv^{-\alpha})$.
The far-tail quantile power is $\alpha(L+1)$.
The hypothesis concerns the joint law, not merely marginal
entrywise tails.
\end{example}
